-- Thread 1 (sort 271): shabbat-as-covenant-sign-protected-day-and-life-saving-defense
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'shabbat-as-covenant-sign-protected-day-and-life-saving-defense',
       'The Shabbat as covenant-sign and protected-day with life-saving-defense override — Jubilees 2, Jubilees 50, and 1 Maccabees 2',
       'Matt 12:1-14''s Shabbat-controversies — the disciples-plucking-grain at vv.1-8 with the *Son of Adam is Lord even of the Shabbat* declaration AND the synagogue-Shabbat-healing of the man-with-the-withered-hand at vv.9-14 with the *kal vachomer* sheep-rescue argument at vv.11-12 — read against the wisdom-stream''s Shabbat-substance architecture. Four moves: Jubilees 2:17 names the Shabbat as the *great sign* of the covenant — the same covenant-sign substance Exodus 31:13 names; Jubilees 2:21 names the Shabbat as the day-of-eating-and-drinking-and-blessing — explicitly the opposite of the Pharisaic-fence-architecture''s reading of restrictive-against-eating; Jubilees 50:12 names the late-Jubilees Shabbat-prohibition code that documents the Second-Temple stringency the Pharisaic-fence inherited and intensified; 1 Maccabees 2:41 names the Hasmonean Shabbat-defense decision that life-saving-overrides-Shabbat-restriction was the operative-principle the wisdom-stream itself had locked under threat of extinction. The framework reads the cluster as locking the framework''s reading of Matt 12:1-14 against the institutional-Christian Sunday-Law tradition: the King restores the Shabbat-substance against both the Pharisaic-fence-architecture AND any reading that takes *Lord of the Shabbat* as authorization to abolish what the wisdom-stream witnesses as the covenant-sign Yahuah (God) himself established at Bereshit (Genesis) 2:3 and Exodus 31:13.',
       sv.verse_id, ev.verse_id, 'complete_study', 271
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 12 AND ev.verse_number = 14
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 272): mercy-as-true-offering-alms-deliver-from-death-in-sirach-and-tobit
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'mercy-as-true-offering-alms-deliver-from-death-in-sirach-and-tobit',
       'Mercy as the true offering and alms as deliverance from death — the second Hosea 6:6 citation in framework-register, Sirach 34-35 and Tobit 4',
       'Matt 12:7''s second Hosea 6:6 citation in Matthew — *if ye had known what this meaneth, I will have mercy, and not sacrifice, ye would not have condemned the guiltless* — read against the wisdom-stream''s mercy-as-true-offering and alms-as-deliverance-from-death architecture. Three moves: Sirach (Ecclesiasticus) 35:1 names the wisdom-stream''s direct mercy-substance-IS-the-true-sacrifice architecture — *he that keepeth the law bringeth offerings enough*; Sirach 34:18 names the heart-substance-required-for-the-sacrifice-to-be-accepted architecture — sacrifice without mercy-substance is rejected; Tobit 4:10 names THE strongest wisdom-stream verbal-anchor for the mercy-as-substance-with-eternal-weight architecture — *alms doth deliver from death, and shall not suffer thee to come into darkness.* The framework reads the cluster as the wisdom-stream restatement of Hosea 6:6 that locks the framework''s reading of Matt 12:7 against any reading of mercy as a soft-side of the Torah: mercy is the operative-substance with eternal-weight; the credential-without-substance (the Pharisaic Shabbat-fence-adherence-without-mercy) is the rejected-offering at every register from the wisdom-stream to the gospel. The same Hosea 6:6 diagnostic from Matt 9:13 (table-fellowship-with-sinners) lands again at Matt 12:7 (Shabbat-keeping-without-mercy) — one diagnostic across both Pharisaic counterfeit-righteousness controversies.',
       sv.verse_id, ev.verse_id, 'complete_study', 272
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 7
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 12 AND ev.verse_number = 7
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 273): eschatological-reversal-righteous-stands-before-those-who-condemned-him
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'eschatological-reversal-righteous-stands-before-those-who-condemned-him',
       'The eschatological reversal — the righteous stands in great boldness before those who condemned him — Wisdom of Solomon 5 and 1 Enoch 95',
       'Matt 12:14''s Pharisaic-council-to-destroy — *then the Pharisees went out, and held a council against him, how they might destroy him* — read against the wisdom-stream''s eschatological-reversal-of-the-righteous-condemned architecture. Three moves: Wisdom of Solomon 5:1 names the wisdom-stream''s direct articulation — *then shall the righteous man stand in great boldness before the face of such as have afflicted him* — the eschatological-reversal at the day-of-judgment; Wisdom 5:4-5 names the system''s-belated-recognition — *we fools accounted his life madness, and his end to be without honour: How is he numbered among the children of Elohim (God)*; 1 Enoch 95:7 names the woe-against-the-persecutors-of-the-righteous architecture — *woe to you, sinners, who persecute the righteous.* The framework reads the cluster against Matt 12:14''s trajectory-from-challenging-the-disciples (Matt 9:11) to slandering-the-King (Matt 11:18-19) to plotting-destruction (Matt 12:14): the same trajectory the wisdom-stream had named at its eschatological-end-point. The day-of-judgment reverses the verdict the system rendered in the present age; the King at Matt 12:14 walks toward the cross under the same architecture; the resurrection is the operative-vindication; and the same architecture operates today against the heart-Torah-walking kingdom-citizens with the same eschatological-reversal awaiting.',
       sv.verse_id, ev.verse_id, 'complete_study', 273
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 14
