-- Thread 4 (sort 274): spirit-anointed-elect-one-the-spirit-of-wisdom-on-the-son-in-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'spirit-anointed-elect-one-the-spirit-of-wisdom-on-the-son-in-1-enoch',
       'The Spirit-anointed Elect-One — the spirit of wisdom and the spirit of righteousness poured out on the Son — 1 Enoch 49 and 62',
       'Matt 12:18-21''s citation of Yeshayahu (Isaiah) 42:1-4 — *behold my servant, whom I have chosen ... I will put my spirit upon him* — read against 1 Enoch''s wisdom-stream articulation of the Spirit-anointing on the Elect-One. Three moves: 1 Enoch 49:1 names the wisdom-poured-out-on-the-Elect-One architecture; 1 Enoch 49:3 names the four-spirits-on-the-Elect-One — the same Isaiah 11:2 four-spirits-cluster (the spirit of wisdom and understanding, of counsel and might, of knowledge and of the fear of Yahuah (the LORD)) applied directly to the Elect-One; 1 Enoch 62:2 names the Elect-One enthroned with the spirit-of-righteousness poured out upon him and the word-of-his-mouth as the operative-instrument at the day-of-judgment. The framework reads the cluster against Matt 12:18-21: the Tanakh-anchor (Isaiah 42:1-4 / 11:2), the wisdom-stream restatement (1 Enoch 49 / 62), and the gospel-fulfillment (Matt 12:18-21 / 3:16-17 / 17:5) name one Spirit-anointing-architecture across three registers. The present-age ministry stages the credentialing-in-mercy-substance (Matt 12:19-20''s meek-King-disposition and bruised-reed-mercy); the eschatological-consummation lands the judgment-unto-victory (Matt 12:20c) at the second-coming the wisdom-stream had named at the throne-of-glory register.',
       sv.verse_id, ev.verse_id, 'complete_study', 274
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 18
