-- Thread 5 (sort 275): compassion-on-the-bruised-cry-of-the-widow-and-orphan-in-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'compassion-on-the-bruised-cry-of-the-widow-and-orphan-in-sirach',
       'Compassion on the bruised and the cry of the widow and orphan — the bruised-reed mercy-substance — Sirach 4 and 35',
       'Matt 12:20''s *a bruised reed shall he not break, and smoking flax shall he not quench, till he send forth judgment unto victory* — read against the wisdom-stream''s articulation of the compassion-on-the-bruised-and-the-cry-of-the-widow-and-orphan architecture. Three moves: Sirach (Ecclesiasticus) 4:1-2 names the wisdom-stream''s direct kingdom-citizens'' disposition — do not defraud-the-poor, do not make-the-needy-eyes-wait, do not make-the-hungry-soul-sorrowful, do not provoke-the-man-in-distress; Sirach 4:4-5 names the compassion-disposition — do not reject-the-supplication, do not turn-the-face-away, do not turn-the-eye-from-the-needy; Sirach 35:13-14 names THE strongest wisdom-stream verbal-anchor for the cry-of-the-bruised-heard-by-Yahuah (God) architecture — *he will not despise the supplication of the fatherless; nor the widow, when she poureth out her complaint. Do not the tears run down the widow''s cheek? and is not her cry against him that causeth them to fall?* The framework reads the cluster against Matt 12:20: the mercy-substance the Yeshayahu (Isaiah) 42 prophet names of the King is the same substance the wisdom-stream named as the disposition required of the kingdom-citizens. The Pharisaic-system''s pattern of categorical-classification-and-dismissal of the bruised-and-the-smoking inverts both the wisdom-stream-disposition and the King''s-disposition; the King restores, the system breaks-and-snuffs, and the system''s plot at Matt 12:14 is precisely the act-causing-the-tears Sirach 35:14 had named.',
       sv.verse_id, ev.verse_id, 'complete_study', 275
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 20
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 12 AND ev.verse_number = 20
