-- Thread 6 (sort 276): binding-of-the-watchers-typological-anchor-for-binding-the-strong-man
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'binding-of-the-watchers-typological-anchor-for-binding-the-strong-man',
       'The binding of the Watchers — Azazel hand-and-foot, the chains prepared for the hosts, nine-tenths bound — as typological-anchor for binding the strong-man — 1 Enoch 10, 1 Enoch 54, Jubilees 10',
       'Matt 12:28-29''s *if I cast out devils by the Spirit of Elohim (God), then the kingdom of Elohim (God) is come unto you. Or else how can one enter into a strong man''s house, and spoil his goods, except he first bind the strong man? and then he will spoil his house* — read against the wisdom-stream''s binding-of-the-watchers architecture. Three moves: 1 Enoch 10:4-5 names the binding-of-Azazel — hand-and-foot, cast-into-the-darkness, sealed-with-rocks, covered-with-darkness for the appointed-time; 1 Enoch 54:5 names the chains-prepared-for-Azazel-and-his-hosts and the casting-into-the-abyss-of-complete-condemnation; Jubilees 10:9-11 names the watchers-bound-with-a-tenth-permitted architecture — nine-tenths bound in the place-of-condemnation, one-tenth permitted before Satan on the earth. The framework reads the cluster against Matt 12:29: the King''s exorcisms-and-spoiling are the inaugurated-form of the binding-architecture the wisdom-stream had named at the watcher-leader register; the full-binding-of-Satan at Revelation 20:1-3 lands the architecture at the millennial-consummation; the brief-final-loosing at Rev 20:7-10 lands the architecture''s terminus. The kingdom-citizens operate in the inaugurated-binding-substance now; the full-binding lands at the consummation; and the King''s exorcisms-as-spoiling at Matt 12:28-29 are the visible-evidence of the kingdom-arrival the wisdom-stream had named.',
       sv.verse_id, ev.verse_id, 'complete_study', 276
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 28
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 12 AND ev.verse_number = 29
ON CONFLICT (slug) DO NOTHING;

-- Thread 7 (sort 277): no-forgiveness-for-the-hardened-disposition-in-jubilees-and-1-enoch-and-wisdom
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'no-forgiveness-for-the-hardened-disposition-in-jubilees-and-1-enoch-and-wisdom',
       'No forgiveness for the hardened disposition — the deliberate covenant-rejection, the no-place-of-repentance, the cogitation that would never be changed — Jubilees 15, 1 Enoch 65, Wisdom of Solomon 12',
       'Matt 12:31-32''s framework-major blasphemy-against-the-Ruach warning — *the blasphemy against the Ruach HaKodesh (Holy Spirit) shall not be forgiven unto men ... neither in this world, neither in the world to come* — read against the wisdom-stream''s no-forgiveness-for-the-hardened-disposition architecture. Three moves: Jubilees 15:33-34 names the great-wrath-no-forgiveness for the deliberate-covenant-rejection — *there will be great wrath from Yahuah (the Lord) ... because they have forsaken His covenant and have turned aside from His word*; 1 Enoch 65:11 names THE direct wisdom-stream verbal-anchor for the no-place-of-repentance architecture — those who have witnessed-the-sin and rejected-the-sentence have *no place of repentance for them*; Wisdom of Solomon 12:10 names the cogitation-that-would-never-be-changed architecture — Yahuah (God) gives place-of-repentance not being-ignorant of the bred-in malice and the cogitation that will-never-be-changed. The framework reads the cluster against Matt 12:31-32''s warning: the wisdom-stream knew the hardened-disposition-against-correction as a possibility-of-the-heart; the deliberate-attribution of the Ruach''s-credentialing-work to demonic-agency by those who have seen the credentialing-clearly IS that hardened-disposition. The framework''s pastoral-reading holds: those who FEAR they have committed it almost certainly have not — the fear is itself evidence of conscience-still-functioning; the hardening-into-the-disposition has not taken hold. The same diagnostic operates against the institutional-religious-system''s historical pattern of rebranding the Ruach''s-work as something else — Pharisees, Galatian agitators, institutional Christianity, modern Hebrew Roots'' false-inclusion gospel, Islam — four costumes on one architecture; the contrary-to-Torah test of 1 John 2:3-4 identifies the lie in any of them.',
       sv.verse_id, ev.verse_id, 'complete_study', 277
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 31
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 12 AND ev.verse_number = 32
ON CONFLICT (slug) DO NOTHING;

-- Thread 8 (sort 278): tongue-as-trial-of-the-heart-words-as-fruit-of-the-tree-in-sirach-27
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'tongue-as-trial-of-the-heart-words-as-fruit-of-the-tree-in-sirach-27',
       'The tongue as the trial of men — the fruit declareth if the tree have been dressed — Sirach 27 and Wisdom of Solomon 1',
       'Matt 12:33-37''s tree-by-its-fruit / out-of-the-abundance-of-the-heart-the-mouth-speaketh / every-idle-word eschatological-accountability cluster — read against the wisdom-stream''s tongue-as-trial-of-the-heart architecture. Three moves: Sirach (Ecclesiasticus) 27:6 names THE strongest wisdom-stream verbal-anchor for the tree-by-fruit / utterance-by-heart architecture — *the fruit declareth if the tree have been dressed; so is the utterance of a conceit in the heart of man*; Sirach 27:7 names speech-as-the-trial-of-men — *praise no man before thou hearest him speak; for this is the trial of men*; Wisdom of Solomon 1:11 names the no-word-goes-for-nought-and-the-mouth-that-belieth-slays-the-soul architecture — *no word so secret, that shall go for nought: and the mouth that belieth slayeth the soul.* The framework reads the cluster against Matt 12:33-37: the wisdom-stream had named the words-are-fruit-of-the-heart architecture in precisely the substance the King walks at Matt 12:33-35; the day-of-judgment at Matt 12:36 is the cosmic-version of the speech-as-trial architecture Sirach 27:7 had named — the words-spoken are the evidence-of-the-heart-substance the judgment will weigh. *By thy words thou shalt be justified, and by thy words thou shalt be condemned* (Matt 12:37) walks the architecture the wisdom-stream had named at the eternal-weight register.',
       sv.verse_id, ev.verse_id, 'complete_study', 278
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
