-- Thread 9 (sort 279): resurrection-from-sheol-gates-of-the-dead-give-back-in-wisdom-and-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'resurrection-from-sheol-gates-of-the-dead-give-back-in-wisdom-and-1-enoch',
       'Resurrection from Sheol — the gates of the dead give back what they have received — the sign-of-Yonah three-days-three-nights architecture — Wisdom of Solomon 16, 1 Enoch 51, Jubilees 23',
       'Matt 12:38-42''s sign-of-Yonah refusal-and-promise — *as Yonah (Jonah) was three days and three nights in the whale''s belly; so shall the Son of Adam be three days and three nights in the heart of the earth* — read against the wisdom-stream''s resurrection-from-Sheol architecture. Three moves: Wisdom of Solomon 16:13 names the direct gates-of-Sheol-and-bring-up-again architecture — *thou hast power of life and death: thou leadest to the gates of Sheol, and bringest up again*; 1 Enoch 51:1 names the earth-and-Sheol-and-hell-giving-back architecture — *the earth also give back that which has been entrusted to it, And Sheol also shall give back that which it has received*; Jubilees 23:30 names the rise-up-and-see-great-peace architecture — *the Lord will heal His servants, And they shall rise up and see great peace.* The framework reads the cluster against Matt 12:40: the sign-of-Yonah is the resurrection-credential pre-announcement — three-days-and-three-nights of the King''s-future death-and-burial-and-resurrection. The wisdom-stream knew the descent-to-Sheol-and-bring-up-again architecture; the King at Matt 12:40 names the inaugurated-form in his own future-resurrection. The framework holds the literal three-days-and-three-nights count; the Friday-evening-to-Sunday-morning traditional Christian reading does not preserve the literal substance.',
       sv.verse_id, ev.verse_id, 'complete_study', 279
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 40
