-- Thread 10 (sort 280): adam-and-the-inherited-evil-heart-needing-the-new-heart-cleansing
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'adam-and-the-inherited-evil-heart-needing-the-new-heart-cleansing',
       'Adam and the inherited evil-heart needing the new-heart cleansing — the empty-house parable architecture — 2 Esdras 7 and Jubilees 1',
       'Matt 12:43-45''s unclean-spirit-returning empty-house parable — *when the unclean spirit is gone out of a man ... when he is come, he findeth it empty, swept, and garnished. Then goeth he, and taketh with himself seven other spirits more wicked than himself ... and the last state of that man is worse than the first* — read against the wisdom-stream''s articulation of the Adam-inherited-evil-heart needing the new-heart-cleansing. Three moves: 2 Esdras (4 Ezra) 7:48 names the inherited-from-Adam architecture — *O Adam, what hast thou done? for though it was thou that sinned, thou art not fallen alone, but we all that come of thee*; 2 Esdras 7:118 restates the architecture explicitly; Jubilees 1:23 names the wisdom-stream''s direct Tanakh-anchor parallel to Yirmeyahu (Jeremiah) 31:33 and Yechezk''el (Ezekiel) 36:26-27 — *I shall create in them a holy spirit, and I shall cleanse them so that they shall not turn away from Me.* The framework reads the cluster against Matt 12:43-45: the cleansed-house empty-of-the-new-heart is the architecture Jubilees 1:23''s new-heart-and-holy-spirit-and-cleansing-substance describes by its negative-correlate — deliverance-without-internal-replacement leaves the children-of-Adam without the internal-substance, vulnerable to deeper bondage. The institutional-Christian altar-call-without-Torah-substance conversion-pattern walks the same structural-vulnerability — old bondage removed, new house left empty because the antinomian-reading of the gospel that produced the conversion removed the heart-Torah-walking life as the internal-furnishing the new-heart-substance places. Kefa''s (Peter''s) apostolic restatement at 2 Peter 2:20-21 names the same architecture: *the latter end is worse with them than the beginning.*',
       sv.verse_id, ev.verse_id, 'complete_study', 280
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 12 AND sv.verse_number = 43
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 12 AND ev.verse_number = 45
