-- Thread 11 (sort 281): children-of-elohim-by-doing-the-fathers-will-in-wisdom-and-sirach-and-jubilees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'children-of-elohim-by-doing-the-fathers-will-in-wisdom-and-sirach-and-jubilees',
       'Children of Elohim by doing the Father''s will — the son-of-the-Most-High identity-marker — Wisdom of Solomon 2, Sirach 4, Jubilees 1',
       'Matt 12:46-50''s kingdom-family-redefinition closing — *whosoever shall do the will of my Father which is in heaven, the same is my brother, and sister, and mother* — read against the wisdom-stream''s children-of-Elohim-by-doing-the-Father''s-will architecture. Four moves: Wisdom of Solomon 2:13-15 names the child-of-Elohim-by-the-righteous-disposition architecture — *he calleth himself the child of Yahuah (the Lord) ... his life is not like other men''s, his ways are of another fashion*; Wisdom of Solomon 2:18 names the son-of-Elohim-tested-by-deliverance architecture — *if the just man be the son of Elohim (God), he will help him*; Sirach (Ecclesiasticus) 4:10 names THE strongest wisdom-stream verbal-anchor for the doing-the-Father''s-substance-makes-thee-a-son architecture — *be as a father unto the fatherless ... so shalt thou be as the son of the most High*; Jubilees 1:24 names the souls-cleaving-to-Yahuah-and-fulfilling-the-commandments yields the Father-and-children-relation architecture — *they will fulfil My commandments, and I shall be their Father and they will be My children.* The framework reads the cluster against Matt 12:50: the kingdom-family-recognition-criterion is the same doing-the-Father''s-will substance the wisdom-stream had named as the operative-form of the son-of-the-Most-High identity. The same criterion is the kingdom-entry-criterion at Matt 7:21 (*not every one that saith unto me, Lord, Lord, shall enter into the kingdom of heaven; but he that doeth the will of my Father*), and the 1 John 2:3-4 master-filter restates it: *if we keep his commandments.* The wisdom-stream and the gospel name one architecture across two registers — the kingdom-family is identified by the heart-Torah-walking-disposition the prophets named, the wisdom-stream named, and the King names operative in the kingdom''s inauguration.',
       sv.verse_id, ev.verse_id, 'complete_study', 281
  FROM _s142_verse_lookup sv, _s142_verse_lookup ev
